## 最简版（仅首发立即执行）

```js
function throttle(fn, wait) {
  let last = 0;
  return function (...args) {
    const now = Date.now();
    if (now - last >= wait) {
      last = now;
      fn.apply(this, args);
    }
  };
}
```

缺点：最后一次调用如果落在冷却期内，会被直接丢弃（无 trailing 补偿）。

---

## 完整版（支持 leading / trailing / cancel / flush）

```js
function throttle(fn, wait = 0, options = {}) {
  if (typeof fn !== 'function') throw new TypeError('fn must be a function');

  const leading  = options.leading  !== false; // 首次是否立即执行，默认 true
  const trailing = options.trailing !== false; // 冷却结束后是否补一次，默认 true

  let timer = null;
  let lastArgs = null;
  let lastThis = null;
  let lastInvokeTime = 0; // 上次真正执行的时间戳
  let started = false;    // 是否已初始化过起始时间

  function invoke(time) {
    lastInvokeTime = time;
    const args = lastArgs;
    const thisArg = lastThis;
    lastArgs = lastThis = null;
    fn.apply(thisArg, args);
  }

  function throttled(...args) {
    const now = Date.now();

    // 首次调用：若不允许 leading，则把起点设为 now，使第一次执行延后一个 wait
    if (!started) {
      started = true;
      if (!leading) lastInvokeTime = now;
    }

    const remaining = wait - (now - lastInvokeTime);

    lastArgs = args;
    lastThis = this;

    // remaining > wait 说明系统时间被回拨，直接重置执行
    if (remaining <= 0 || remaining > wait) {
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      invoke(now);
    } else if (!timer && trailing) {
      // 冷却期内，安排一次延迟执行（只安排一次）
      timer = setTimeout(() => {
        timer = null;
        invoke(Date.now());
      }, remaining);
    }
  }

  // 取消挂起的执行并重置状态
  throttled.cancel = function () {
    if (timer) clearTimeout(timer);
    timer = null;
    lastArgs = lastThis = null;
    lastInvokeTime = 0;
    started = false;
  };

  // 立即执行挂起的那次调用
  throttled.flush = function () {
    if (timer && lastArgs) {
      clearTimeout(timer);
      timer = null;
      invoke(Date.now());
    }
  };

  return throttled;
}
```

---

## 使用示例

```js
const onScroll = throttle(
  (e) => console.log('scroll', window.scrollY, Date.now() - start),
  300
);

let start = Date.now();

// 快速连续触发
onScroll();  // ~0ms    立即执行（leading）
onScroll();  // 丢弃
onScroll();  // 300ms 左右补执行一次（trailing）

// 组件卸载时清理，避免内存泄漏
onScroll.cancel();
```

## 几个要点

1. **节流 ≠ 防抖**：节流保证「每 wait 毫秒最多执行一次」；防抖是「停止触发 wait 后才执行一次」。
2. **trailing 的价值**：滚动/拖拽结束时你通常希望用最终位置再算一次，所以默认 `trailing: true`。
3. **`lastArgs/lastThis`**：保证 `fn` 的 `this` 和参数与最后一次调用一致。
4. **`cancel()` 很有必要**：定时器持有闭包引用，在组件销毁或事件解绑时必须清理。
5. **`Date.now()` 的坑**：用户调整系统时间可能让 `now` 变小，所以用 `remaining > wait` 兜底。

如果想要更精简但仍带 trailing 的版本：

```js
function throttle(fn, wait) {
  let last = 0, timer = null;
  return function (...args) {
    const now = Date.now();
    const remaining = wait - (now - last);
    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = now;
      fn.apply(this, args);
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}
```
